const eipL = (topic, body, example, keyPoints, simple) => ({ id: 'le_' + topic, topic, minutes: 4, sources: ['eipass_std', 'digcomp'], body, example, keyPoints, simple });
export const EIP_LESSONS = [
  eipL('e1_problemi', "Prima di chiamare qualcuno, si controllano le cose semplici, in ordine. Se manca Internet: ==Wi-Fi acceso==, ==modalità aereo spenta==, password della rete giusta, poi ==riavvio del router==.\n\nSe il PC è lento ad accendersi, si riducono i ==programmi che partono all'avvio==. Per la batteria: ==luminosità più bassa==, risparmio energetico attivo, Wi-Fi e Bluetooth spenti quando non servono.\n\nFotocamera o microfono che non vanno: si controlla che l'app abbia il ==permesso== (Impostazioni → Privacy e sicurezza), che sia scelto il dispositivo giusto e che i ==driver== siano aggiornati.", "In videochiamata nessuno ti sente: guardi se il microfono è disattivato nell'app, poi se l'app ha il permesso di usarlo.", ['Prima le verifiche semplici', 'Modalità aereo spegne tutte le connessioni', 'Riavviare il router', 'Permessi e driver per webcam e microfono'], "Come con una lampada che non si accende: prima guardi la spina, poi la lampadina, poi chiami l'elettricista."),
  eipL('e1_cloud', "Il ==cloud== è spazio e potenza di calcolo su server raggiungibili via Internet. Esempi: ==Google Drive==, ==OneDrive==.\n\nVantaggi: file disponibili ==da ogni dispositivo==, condivisione facile, niente spazio occupato sul PC. Rischi: serve la ==connessione==, si dipende dal ==fornitore==, i dati sono fuori dal proprio computer.\n\nAttenzione: la ==sincronizzazione== copia anche le cancellazioni; un ==backup== è invece una copia separata che resta.", "Il collega cancella per errore un file dalla cartella sincronizzata: sparisce anche dal tuo PC. Per questo serve anche un backup.", ['Cloud = file e programmi su server via Internet', 'Pro: ovunque e condivisibile', 'Contro: connessione e fornitore', 'Sincronizzare non è fare backup'], 'Il cloud è un armadio in affitto: lo apri da qualsiasi casa, ma la chiave è la tua password.'),
  eipL('e1_bisogni', "Per ==acquistare online== si controlla che il sito sia affidabile: ==https==, dati del venditore, recensioni. Si paga con strumenti sicuri (==PayPal==, carte prepagate) e mai fuori dalla piattaforma. Nell'UE c'è in genere il ==diritto di recesso di 14 giorni==.\n\nWindows ha strumenti di ==accessibilità==: lente di ingrandimento, temi a contrasto elevato, ==Assistente vocale== (legge lo schermo), puntatore più grande.\n\n==Google Traduttore== traduce testo, documenti, siti, foto e conversazioni; scaricando la lingua funziona anche ==offline==.", "Un venditore ti chiede un bonifico «così risparmi le commissioni»: se paghi fuori dalla piattaforma, perdi le sue tutele.", ['https + venditore identificabile', 'Recesso: 14 giorni', 'Assistente vocale = lettore di schermo', 'Traduttore anche offline con il pacchetto lingua'], 'Online valgono le regole del negozio vero: guardi chi vende e paghi alla cassa, non nel retro.'),
  eipL('e1_crescita', "L'==intelligenza artificiale== impara dai dati. Il ==machine learning== impara da esempi; il ==deep learning== usa reti neurali a molti strati; nell'==apprendimento per rinforzo== il sistema prova e riceve premi o penalità. Oggi esiste solo l'IA ==«ristretta»==, specializzata in compiti precisi.\n\nUn sistema automatico può sbagliare se è addestrato su ==dati incompleti o distorti==. L'UE regola l'IA con l'==AI Act==, che classifica i sistemi per ==livello di rischio==.\n\nLe competenze digitali vanno aggiornate per tutta la vita (==lifelong learning==). Contro le notizie false aiutano i siti di ==fact-checking== e la consapevolezza dei ==bias cognitivi==.", 'Un programma che seleziona curricula, addestrato su vecchie assunzioni quasi tutte maschili, tende a scartare le donne: riproduce i difetti dei dati.', ['IA impara dai dati', 'Dati distorti = decisioni distorte', 'AI Act: classi di rischio', 'Bias e fact-checking'], "L'IA è uno studente che ha letto moltissimo: se i libri erano sbagliati, sbaglia anche lui."),
  eipL('e2_navigare', "Il ==browser== (Chrome, Edge, Firefox) è il programma per visitare il Web. L'==URL== è l'indirizzo della pagina: in https://www.istruzione.it/graduatorie-ata/ il ==dominio== è istruzione.it.\n\n==Internet== è la rete; il ==Web== è uno dei servizi che la usano. Un link si apre in una ==nuova scheda== con tasto destro o ==Ctrl + clic==. ==F5== ricarica la pagina.\n\nIl ==lucchetto/https== indica una connessione ==cifrata== e un ==certificato== che attesta l'identità del sito. Non garantisce che il sito sia onesto: anche un sito di phishing può avere il lucchetto.", 'Ricevi un link «per aggiornare i dati della banca»: c\'è il lucchetto, ma il dominio è strano. Non inserisci nulla.', ['Browser ≠ motore di ricerca', 'Il dominio dice chi è il sito', 'https = cifrato, non = onesto', 'Ctrl + clic = nuova scheda'], "L'https è una busta chiusa: nessuno legge la lettera, ma non ti dice se il destinatario è una brava persona."),
  eipL('e2_ricerca', "Un ==motore di ricerca== trova pagine a partire da parole chiave. Operatori utili: ==\"frase esatta\"== tra virgolette, ==-parola== per escludere, ==site:== per cercare in un solo sito, ==filetype:pdf== per un tipo di file.\n\nI risultati sono ==personalizzati== in base a posizione e cronologia; quelli ==sponsorizzati== sono pubblicità. I ==cookie== sono piccoli file che i siti salvano nel browser; servono anche alla ==profilazione==, cioè costruire un profilo dei tuoi gusti.\n\nI cookie si gestiscono dalle impostazioni del browser. Motori come ==DuckDuckGo== non profilano le ricerche.", 'Per trovare solo i documenti ufficiali scrivi: graduatorie ata site:istruzione.it filetype:pdf', ['Virgolette, meno, site:, filetype:', 'Sponsorizzato = pubblicità', 'Cookie e profilazione', 'Risultati diversi per persone diverse'], 'Il motore di ricerca è un bibliotecario che ti conosce: a volte troppo.'),
  eipL('e2_valutare', "La ==misinformazione== è un contenuto falso diffuso ==senza volerlo==; la ==disinformazione== è falsa e diffusa ==apposta== per ingannare. Forme tipiche: satira presa sul serio, ==falso contesto== (foto vera ma di un altro evento), ==falsa connessione== (titolo che non c'entra col testo), contenuto manipolato.\n\nPer valutare: ==fonte, autore, data==, e se altre fonti affidabili confermano. Il ==clickbait== usa titoli sensazionali per avere clic.\n\nLe ==echo chamber== nascono perché gli algoritmi ci mostrano ciò che già ci piace.", 'Gira un messaggio: «Graduatorie ATA anticipate, domande entro venerdì!». Prima di crederci guardi il sito del Ministero.', ['Mis- = senza volerlo, dis- = apposta', 'Fonte, autore, data, conferme', 'Falso contesto e falsa connessione', 'Echo chamber'], 'Una notizia è come un pacco: prima di aprirlo guardi chi lo manda.'),
  eipL('e2_dati', "I ==moduli online== (es. Google Moduli) raccolgono risposte; si possono vedere ==riepilogate== o esportare in un ==foglio di lavoro==.\n\nI ==grafici== rendono i dati visibili: ==a torta== per le parti di un totale, ==a linee== per l'andamento nel tempo, ==a colonne== per confrontare. La ==legenda== spiega colori e serie.\n\nUn ==database== (es. ==LibreOffice Base==) organizza i dati in tabelle: ==record== (righe) e ==campi== (colonne). La ==chiave primaria== identifica ogni record in modo ==univoco==; una ==query== estrae i record che rispondono a criteri.", 'Per un sondaggio tra le famiglie sugli orari dei colloqui crei un modulo online e guardi le risposte in un foglio.', ['Moduli → risposte in un foglio', 'Torta = parti, linee = tempo', 'Record e campi', 'Chiave primaria univoca, query'], "Il database è uno schedario: ogni scheda ha un numero unico, la query è la domanda all'archivista."),
  eipL('e3_comunicare', "In mario.rossi@scuola.it, ==scuola.it è il dominio==. L'==oggetto== è il titolo del messaggio; la ==graffetta== aggiunge allegati. ==Cc== mostra i destinatari a tutti; ==Ccn== li nasconde. ==Inoltra== manda il messaggio a un altro; ==Rispondi a tutti== include tutti i destinatari.\n\nLa ==webmail== si usa dal browser, il ==client== (es. Outlook) è un programma. La ==firma automatica== aggiunge nome e recapiti; la ==risposta automatica== avvisa che sei assente.\n\nNelle ==riunioni online== si spegne il microfono quando non si parla e si usa ==Condividi schermo== per mostrare un documento.", 'Scrivi a tutti i genitori di una classe: indirizzi in Ccn, così nessuno vede quelli degli altri.', ['Ccn nasconde gli indirizzi', 'Inoltra ≠ Rispondi', 'Webmail = browser, client = programma', 'Microfono spento se non parli'], 'Ccn è una busta per ognuno: ciascuno riceve la lettera senza vedere la lista degli invitati.'),
  eipL('e3_condividere', "Su Drive o OneDrive si ==condivide== con l'indirizzo di una persona o con un ==link==. «Chiunque abbia il link» vuol dire che anche chi lo riceve inoltrato può aprire il file.\n\nLe licenze ==Creative Commons== dicono cosa si può fare con un'opera: ==BY== cita l'autore, ==NC== niente usi commerciali, ==ND== niente modifiche, ==SA== condividi allo stesso modo. Le ==OER== sono risorse educative aperte; i ==MOOC== corsi online aperti a tutti.\n\nPer verificare un'immagine si usa la ==ricerca inversa per immagini==; per un sito si guardano «Chi siamo» e i dati legali.", 'Trovi una foto CC BY-NC per il giornalino della scuola: puoi usarla citando l\'autore, perché il giornalino non ha fini commerciali.', ['Link pubblico = chiunque lo abbia', 'BY, NC, ND, SA', 'OER e MOOC', 'Ricerca inversa per immagini'], "La licenza CC è il cartello appeso all'opera: «prendi pure, ma alle mie condizioni»."),
  eipL('e3_cittadinanza', "Per i servizi online della PA si usa l'==identità digitale==: ==SPID==, ==CIE== (carta d'identità elettronica) o ==CNS== (la tessera sanitaria abilitata, con lettore). Con SPID servono nome utente, password e un ==secondo fattore== (app o codice).\n\nEsempi di servizi: ==Istanze Online== del Ministero per le domande, INPS, fascicolo sanitario. Esistono anche servizi basati su ==comunità== (Wikipedia, OpenStreetMap).\n\nIl digitale serve anche alla partecipazione: ==consultazioni pubbliche==, ==petizioni online==, crowdfunding. Ha però rischi: ==disinformazione==, ==micro-targeting== politico, decisioni automatiche poco trasparenti.", 'La domanda per le graduatorie ATA si fa su Istanze Online entrando con SPID o CIE.', ['SPID, CIE, CNS', 'Secondo fattore per SPID', 'Consultazioni e petizioni online', 'Rischi: micro-targeting e algoritmi opachi'], "SPID è la chiave unica dello Stato: una sola chiave per tante porte."),
  eipL('e3_collaborare', "Strumenti per lavorare insieme: ==calendari online== condivisi (si invitano i colleghi, si può dare accesso ==in sola lettura==), ==bacheche online== come ==Padlet==, ==mappe concettuali== con ==CmapTools==.\n\n==Wikipedia== è scritta da una comunità: ogni voce ha la ==cronologia== delle modifiche e una ==pagina di discussione== per confrontarsi. I contenuti devono basarsi su ==fonti verificabili== e su un punto di vista neutrale.", 'Il calendario delle riunioni della segreteria è condiviso in sola lettura con i docenti: vedono le date ma non le cambiano.', ['Inviti e sola lettura', 'Padlet = bacheca', 'CmapTools = mappe', 'Wikipedia: cronologia, discussione, fonti'], 'Il calendario condiviso è la lavagna della sala professori, ma sempre aggiornata.'),
  eipL('e3_netiquette', "La ==netiquette== è la buona educazione online: niente ==MAIUSCOLO== (sembra urlare), tono adatto al contesto e alle persone, discussioni sui fatti.\n\nI contatti molesti si ==bloccano== (WhatsApp, Instagram, email). Gravi comportamenti da riconoscere: ==hate speech== (odio verso persone o gruppi), ==revenge porn== (immagini intime diffuse senza consenso: ==reato==), ==sextortion== (ricatto con immagini intime).\n\n==Accessibilità==: ==screen reader== e riconoscimento vocale aiutano chi ha disabilità.", 'In un gruppo di genitori la discussione si accende: rispondi sui fatti e, se serve, continui in privato.', ['Maiuscolo = urlare', 'Bloccare i molesti', 'Revenge porn è reato', 'Screen reader per l\'accessibilità'], 'Online vale la stessa educazione che useresti allo sportello.'),
  eipL('e3_identita', "L'==identità digitale== è l'insieme delle informazioni che ci rappresentano online; l'==impronta digitale== è la traccia delle nostre attività. Si protegge con password diverse e ==gestori di password==.\n\nPer limitare il ==tracciamento==: cancellare i ==cookie==, ==navigazione in incognito== (non salva cronologia sul dispositivo, ma non rende invisibili), consenso personalizzato ai cookie, ==opt-out== dalla pubblicità mirata, controllo della ==cronologia delle posizioni==. Le foto contengono ==metadati== (data, dispositivo, a volte ==posizione GPS==).\n\nSu ==LinkedIn== si cura il profilo professionale e si sceglie ==chi può vederlo==.", 'Prima di pubblicare la foto di una gita, togli la posizione GPS dai metadati.', ['Impronta digitale online', 'Incognito non è invisibilità', 'Metadati e GPS nelle foto', 'Visibilità del profilo'], 'Online lasci impronte come sulla sabbia: meglio sapere dove cammini.'),
  eipL('e4_dispositivi', "Il ==malware== è software dannoso: ==virus== (ha bisogno di un file ospite), ==worm== (si diffonde da solo), ==trojan== (sembra utile ma non lo è), ==ransomware== (cifra i file e chiede un riscatto), ==spyware==, ==keylogger== (registra i tasti).\n\nIl ==phishing== imita banche o enti per rubare dati; via SMS è ==smishing==, al telefono ==vishing==; il ==pharming== porta a un sito falso anche se scrivi l'indirizzo giusto.\n\nDifese: ==aggiornamenti==, ==antivirus== (in Windows: Sicurezza di Windows / Defender), ==firewall==, password lunghe e diverse, ==autenticazione a più fattori==. Le ==macro== di documenti inattesi non si abilitano.", "Arriva un allegato Word «Fattura» che chiede di abilitare il contenuto: non lo abiliti, è un trucco classico per eseguire codice dannoso.", ['Virus, worm, trojan, ransomware', 'Phishing, smishing, vishing, pharming', 'Aggiornamenti, antivirus, firewall', 'Più fattori di autenticazione'], 'La password è la chiave; il secondo fattore è il portiere che controlla anche il documento.'),
  eipL('e4_privacy', "Il ==GDPR== (Regolamento UE 2016/679) protegge i ==dati personali==. Ci sono dati ==particolari== (salute, origine, religione, opinioni) con più tutele. L'==informativa== spiega quali dati si raccolgono e perché; si ha ==diritto di accesso== ai propri dati.\n\nPer la PA ci si identifica con ==SPID, CIE o CNS==. Nei ==pagamenti online==: siti https, sistemi affidabili, carte prepagate, mai dati della carta via email.\n\nUn'==email sospetta== ha urgenza, mittente strano, errori, link o allegati inattesi. Gli oggetti ==IoT== vanno protetti cambiando la password di fabbrica.", 'Un messaggio chiede di «verificare l\'account della segreteria» entro un\'ora: non clicchi e chiedi conferma per canali ufficiali.', ['GDPR = 2016/679', 'Dati particolari', 'Accesso ai propri dati', 'Email sospette: urgenza + link'], 'I dati personali sono come le chiavi di casa: non si lasciano in giro e non si danno a chi le chiede di fretta.'),
  eipL('e4_benessere', "Il digitale può creare ==dipendenza== e ==stress==. Segnali: ansia senza telefono, perdita di controllo sul tempo. Il ==phubbing== è ignorare chi hai davanti per lo schermo.\n\nStrumenti: ==tempo di utilizzo dello schermo==, limiti alle app, modalità ==«Non disturbare»==, ==controllo genitori==.\n\nRischi da riconoscere: ==cyberbullismo==, ==body shaming==, ==flaming== (litigi aggressivi), ==grooming== (adescamento di minori). Le app usano tecniche che orientano le scelte: ==ricompense imprevedibili==, ==nudging==, ==gamification==, ==clickbait==.", 'Attivi «Non disturbare» durante lo studio: le notifiche arrivano dopo.', ['Phubbing', 'Non disturbare e limiti alle app', 'Cyberbullismo e grooming', 'Nudging e ricompense imprevedibili'], 'Il telefono è un ottimo servitore e un pessimo padrone.'),
  eipL('e4_ambiente', "Anche il digitale inquina: i ==data center== consumano molta energia e la produzione dei dispositivi usa materie prime. Le apparecchiature da buttare sono ==RAEE==: vanno ai centri di raccolta o restituite al negozio.\n\nL'==obsolescenza programmata== è progettare prodotti che durano meno. Buone pratiche: dispositivi ==efficienti, riparabili, durevoli== o ricondizionati, ==risparmio energetico==, spegnere ciò che non serve, meno streaming in alta definizione quando non serve.\n\nIl digitale aiuta anche l'ambiente: sensori che regolano luci e riscaldamento, mobilità condivisa.", 'Il vecchio PC della segreteria non va nel cassonetto: va consegnato come RAEE.', ['RAEE ai centri di raccolta', 'Obsolescenza programmata', 'Efficienza e riparabilità', 'Data center consumano energia'], 'Ogni clic usa un po\' di energia da qualche parte.'),
  eipL('e5_file', "L'==estensione== dice il tipo di file: ==.docx== testo Word, ==.xlsx== Excel, ==.pptx== PowerPoint, ==.pdf== documento che si vede uguale ovunque, ==.jpg/.png== immagini, ==.zip== archivio compresso, ==.csv== tabella in testo semplice. ==.odt/.ods/.odp== sono il formato aperto ==OpenDocument== (LibreOffice).\n\nLe estensioni si mostrano da Esplora file → ==Visualizza → Mostra → Estensioni nomi file==. Le ==proprietà== mostrano tipo, dimensione, date.\n\nUn buon nome di file è ==breve e descrittivo==, senza simboli come / e \\. Una cartella si comprime con tasto destro → ==Comprimi in file ZIP==.", 'verbale_consiglio_2026-10-08.pdf si capisce e si ordina bene; «documento DEFINITIVO 2 bis.docx» no.', ['Estensione = tipo di file', 'PDF per documenti finali', 'ODF = formato aperto', 'Nomi brevi e descrittivi'], "L'estensione è l'etichetta sul barattolo: dice cosa c'è dentro."),
  eipL('e5_documenti', "Nell'elaboratore di testi si ==seleziona== e poi si formatta (scheda Home). Comandi base: ==Ctrl + Z== annulla, ==Ctrl + F== trova, ==Ctrl + H== sostituisci, ==Ctrl + K== collegamento.\n\nUn documento ==accessibile== è chiaro per tutti: carattere semplice e abbastanza grande, ==buon contrasto==, niente foto di sfondo, ==stili di titolo== (Titolo 1, Titolo 2) che permettono di creare l'==indice automatico==, ==testo alternativo== per le immagini, ==tabulazioni== o tabelle invece di tanti spazi.\n\nPer inviarlo si ==esporta in PDF== mantenendo la struttura.", 'Una circolare con titoli a stile, indice automatico ed esportata in PDF si legge bene anche con un lettore di schermo.', ['Ctrl + Z, F, H, K', 'Stili di titolo → indice', 'Contrasto e testo alternativo', 'Esporta in PDF'], 'Gli stili sono i cassetti etichettati del documento: tutto in ordine e facile da trovare.'),
  eipL('e5_contenuti', "Un'==infografica== unisce dati, grafici e immagini; si parte da una ==base dati ordinata==. La ==realtà aumentata (AR)== sovrappone elementi digitali alla realtà vista dalla fotocamera; la ==realtà virtuale (VR)== immerge in un ambiente simulato.\n\nL'IA genera testi e immagini. Un ==deepfake== è un video o audio manipolato con l'IA: segnali sono viso e labiale innaturali, luci incoerenti. I contenuti creati con l'IA si usano con attenzione, dichiarandolo.\n\nAccessibilità: ==sottotitoli automatici== nei video. Per la robotica didattica si usano schede come ==Arduino, Raspberry Pi, micro:bit==.", 'Un video del ministro che annuncia «graduatorie abolite» con il labiale fuori sincrono: probabile deepfake.', ['Infografica = dati + immagini', 'AR sovrappone, VR immerge', 'Deepfake e come riconoscerli', 'Sottotitoli automatici'], "Il deepfake è un trucco da prestigiatore: guardato da vicino, qualcosa non torna."),
  eipL('e5_copyright', "Il ==diritto d'autore== protegge le opere creative (testi, musica, foto, software). In Italia dura in genere per ==tutta la vita dell'autore più 70 anni==. Un'immagine trovata online ==non è automaticamente libera==.\n\nIl software si usa secondo la ==licenza==: ==open source== (codice disponibile e modificabile secondo la licenza), ==freeware== (gratis ma non per forza aperto), proprietario. Le opere si possono usare legalmente con licenze ==Creative Commons== o ==banche di immagini libere==.\n\nLa ==SIAE== è una società di gestione collettiva dei diritti. La ==parodia== è ammessa entro certi limiti.", 'Per il volantino della festa scegli un\'immagine CC BY e scrivi il nome dell\'autore sotto.', ['Vita dell\'autore + 70 anni', 'Online non vuol dire libero', 'Open source vs freeware', 'CC e banche libere'], 'Usare un\'opera altrui è come prendere in prestito un libro: si chiede e si restituisce come pattuito.'),
  eipL('e5_coding', "Un ==algoritmo== è una sequenza ordinata di istruzioni per risolvere un problema; si rappresenta con un ==diagramma di flusso== (il ==rombo== è una decisione).\n\nLe ==strutture di controllo== sono: ==sequenza==, ==selezione== (se… allora… altrimenti) e ==ripetizione== (cicli). L'==input== sono i dati in entrata, l'==output== i risultati.\n\n==Scratch== permette di programmare ==a blocchi==, unendo pezzi come in un puzzle.", "«Se la stampante non stampa → controlla la carta; altrimenti → riavvia»: è una selezione in un algoritmo.", ['Algoritmo = istruzioni in ordine', 'Rombo = decisione', 'Sequenza, selezione, ripetizione', 'Scratch a blocchi'], 'Una ricetta di cucina è un algoritmo.'),
  eipL('e6_dati', "Una cartella di lavoro di ==Excel== (o LibreOffice Calc) contiene ==fogli==; ogni cella ha un indirizzo come ==B3== (colonna e riga). Il ==riempimento automatico== (quadratino in basso a destra) continua serie come 1, 2, 3 o lunedì, martedì.\n\nI ==numeri== si allineano a destra, il ==testo== a sinistra: un numero a sinistra spesso è testo e non entra nei calcoli. Le ==date== sono numeri in formato data. Il ==formato celle== cambia l'aspetto (valuta, percentuale, data) senza cambiare il valore.\n\n==Dati → Ordina== mette in ordine; ==Ctrl + F/H== trova e sostituisce; ==Visualizza → Blocca riquadri== tiene ferme le intestazioni.", 'Un elenco di 200 alunni: blocchi la prima riga per vedere sempre «Cognome, Nome, Classe» mentre scorri.', ['Cella = colonna + riga', 'Riempimento automatico', 'Numeri a destra, testo a sinistra', 'Ordina e Blocca riquadri'], 'Il foglio di calcolo è un quaderno a quadretti che sa fare i conti.'),
  eipL('e6_formule', "Ogni formula inizia con ==\"=\"==. Operatori: + − ==*== (per) ==/== (diviso); prima moltiplicazioni e divisioni, poi somme, salvo ==parentesi==. Funzioni base: ==SOMMA, MEDIA, CONTA.NUMERI, MAX, MIN== e ==SE==. Nell'Excel italiano gli argomenti si separano con il ==punto e virgola==: =SE(A1>=6;\"Sì\";\"No\").\n\nCopiando una formula, i riferimenti ==relativi== (A1) si spostano; quelli ==assoluti== (==$A$1==) restano fissi.\n\nErrori: ==#DIV/0!== divisione per zero, ==#NOME?== funzione scritta male, ==#RIF!== riferimento a celle eliminate, ==####== colonna troppo stretta.", 'Per calcolare la percentuale di ogni voce sul totale in B10 scrivi =B2/$B$10 e la copi verso il basso.', ['Sempre "=" all\'inizio', 'Prima * e /, poi + e −', 'Relativo A1, assoluto $A$1', '#DIV/0!, #NOME?, #RIF!'], 'Il $ è un chiodo: tiene ferma la cella quando copi la formula.'),
  eipL('e6_stampa', "Si salva con ==Ctrl + S==; ==Salva con nome== crea una copia con altro nome, posizione o formato (==.xlsx==, ==.ods==, ==PDF==). Sui file nel cloud il ==salvataggio automatico== registra le modifiche.\n\nPrima di stampare: ==anteprima di stampa==, ==orientamento== (Layout di pagina), ==Adatta a una pagina==, margini, intestazione e piè di pagina. Per ripetere le intestazioni su ogni pagina: ==Stampa titoli → Righe da ripetere in alto==. Per stampare solo una parte: ==Stampa selezione== o area di stampa.", 'Il prospetto turni da mandare al collega: lo esporti in PDF, già impaginato in orizzontale su una pagina.', ['Ctrl + S e Salva con nome', 'Anteprima prima di stampare', 'Adatta a una pagina', 'Righe da ripetere in alto'], "L'anteprima è la prova del vestito prima della festa."),
  eipL('e7_diapo', "Una presentazione (==PowerPoint== o LibreOffice Impress) è fatta di ==diapositive==. ==Home → Nuova diapositiva== ne aggiunge una; il ==layout== decide la disposizione dei segnaposto; il ==tema== coordina colori e caratteri.\n\nNel riquadro delle ==miniature== si duplicano, spostano e selezionano le diapositive (==Ctrl + clic== per più diapositive). ==Inserisci== aggiunge immagini, forme, caselle di testo, simboli, schermate.\n\nGli oggetti si ==allineano==, ==raggruppano==, ==ruotano== e si mettono in ==primo piano== o in secondo piano. Regola d'oro: ==poche parole==, caratteri grandi, buon contrasto.", 'Per l\'open day: una diapositiva per argomento, un titolo, tre punti e una foto.', ['Layout e tema', 'Miniature: duplica, sposta, Ctrl + clic', 'Allinea e raggruppa', 'Poche parole, grande contrasto'], 'Una diapositiva è un cartello stradale, non una pagina di libro.'),
  eipL('e7_gestire', "La ==transizione== è l'effetto tra una diapositiva e l'altra; l'==animazione== riguarda un singolo oggetto (scheda Animazioni, con ==intervallo== «al clic» o «dopo la precedente»). Meglio ==pochi effetti coerenti==.\n\n==F5== avvia dall'inizio, ==Maiusc + F5== dalla diapositiva corrente, ==Esc== esce; si avanza con frecce, spazio o clic. ==Nascondi diapositiva== la salta senza cancellarla. Le ==note del relatore== le vede solo chi presenta.\n\nSi controlla l'ortografia (==F7==), si aggiunge il piè di pagina (Inserisci → Intestazione e piè di pagina), si stampano gli ==stampati== (più diapositive per foglio) e si esporta in ==PDF== per chi deve solo leggere.", 'Prima di presentare in collegio nascondi la diapositiva con i dati provvisori e controlli l\'ortografia.', ['Transizione ≠ animazione', 'F5, Maiusc + F5, Esc', 'Nascondi diapositiva', 'Stampati e PDF'], 'Le animazioni sono il sale: un pizzico va bene, troppo rovina il piatto.')
];

