    [1, "=MAX(C1:C10) restituisce:", ["Il valore più grande dell'intervallo", "Il più piccolo", "La somma", "La media"], "MIN restituisce il più piccolo."],
    [1, "Nelle formule, il simbolo della moltiplicazione è:", ["*", "x", ":", "×"], "La divisione è /."],
    [1, "I due punti in A1:A10 indicano:", ["Un intervallo di celle da A1 ad A10", "Una divisione", "Solo due celle", "Un errore"], "Comprende tutte le celle tra A1 e A10."],
    [2, "=CONTA.NUMERI(A1:A10):", ["Conta le celle che contengono numeri", "Somma i numeri", "Conta tutte le celle", "Conta le celle con testo"], "Le celle con testo o vuote non vengono contate."],
    [2, "Qual è il risultato di =10+2*3?", ["16", "36", "15", "12"], "Prima la moltiplicazione (2*3=6), poi la somma."],
    [2, "=MIN(4;9;2) restituisce:", ["2", "9", "4", "15"], "Il valore più piccolo tra quelli indicati."],
    [2, "Nella versione italiana di Excel gli argomenti delle funzioni si separano con:", ["Il punto e virgola", "La virgola", "Il punto", "Lo spazio"], "La virgola è il separatore dei decimali."],
    [2, "Copi la formula =A1*2 dalla cella B1 alla cella B2. Diventa:", ["=A2*2", "=A1*2", "=B2*2", "=A1*3"], "I riferimenti relativi si spostano insieme alla formula."],
    [2, "L'errore #DIV/0! indica:", ["Una divisione per zero o per una cella vuota", "Un nome di funzione sbagliato", "Un riferimento eliminato", "Un numero troppo grande"], "Controlla il divisore."],
    [3, "Un riferimento assoluto si scrive:", ["$A$1", "A1", "#A1", "&A1"], "Il $ blocca colonna e riga quando copi."],
    [3, "Copi =B2*$E$1 nella riga sotto. Diventa:", ["=B3*$E$1", "=B3*$E$2", "=B2*$E$1", "=C2*$E$1"], "B2 è relativo e scende; $E$1 è assoluto e resta."],
    [3, "L'errore #NOME? compare quando:", ["Excel non riconosce il nome di una funzione, ad esempio scritta male", "Si divide per zero", "Manca un foglio", "La colonna è stretta"], "Es. =SOMA(A1:A3) invece di =SOMMA(A1:A3)."],
    [3, "L'errore #RIF! compare quando:", ["La formula si riferisce a celle non più valide, ad esempio eliminate", "Si divide per zero", "Il nome della funzione è sbagliato", "Il numero è negativo"], "Succede spesso dopo aver eliminato righe o colonne."],
    [3, "=SE(A1>=6;\"Promosso\";\"Respinto\") con A1 uguale a 5 restituisce:", ["Respinto", "Promosso", "5", "FALSO"], "La condizione 5>=6 è falsa, quindi si usa il terzo argomento."],
    [3, "Qual è il risultato di =(10+2)*3?", ["36", "16", "15", "30"], "Le parentesi si calcolano per prime."],
    [4, "In =SE(B2>100;B2*0,9;B2) con B2 uguale a 200, il risultato è:", ["180", "200", "90", "100"], "200 > 100 è vero, quindi 200 × 0,9 = 180."],
    [4, "In C2 vuoi la percentuale di B2 sul totale in B10, e poi copiare la formula verso il basso. Cosa scrivi?", ["=B2/$B$10", "=B2/B10", "=$B$2/B10", "=B10/B2"], "Il totale deve restare fisso: $B$10."],
    [4, "Dopo un calcolo una cella mostra ####. Di solito significa che:", ["La colonna è troppo stretta per mostrare il valore", "La formula è sbagliata", "Il file è danneggiato", "C'è un virus"], "Allarga la colonna con un doppio clic sul bordo dell'intestazione."],
    [1, "Calcola somma e media di cinque numeri.", ["10", "50", "12", "8"], "La somma è 50; la media è 50 diviso 5, cioè 10.", ["Apri Excel (o LibreOffice Calc) e crea una cartella di lavoro vuota.", "Nelle celle da A1 ad A5 scrivi: 12, 7, 20, 3, 8.", "In A6 scrivi =SOMMA(A1:A5) e premi Invio.", "In A7 scrivi =MEDIA(A1:A5) e premi Invio.", "Domanda: che numero compare in A7?"]],
    [3, "Copia una formula con un riferimento assoluto.", ["100", "50", "0", "#RIF!"], "B3 contiene =A3*$C$1, cioè 50 × 2 = 100: il $ ha tenuto ferma la cella C1.", ["In un foglio vuoto scrivi 10 in A1, 20 in A2, 50 in A3.", "In C1 scrivi 2.", "In B1 scrivi =A1*$C$1 e premi Invio.", "Clicca B1 e trascina il quadratino in basso a destra fino a B3.", "Domanda: che valore compare in B3?"]],
    [3, "Usa la funzione SE.", ["Sufficiente", "Insufficiente", "7", "#NOME?"], "Con A1 = 7 la condizione A1>=6 è vera, quindi compare il secondo argomento.", ["In un foglio vuoto scrivi 5 in A1.", "In B1 scrivi =SE(A1>=6;\"Sufficiente\";\"Insufficiente\") e premi Invio: compare Insufficiente.", "Ora in A1 scrivi 7 e premi Invio.", "Domanda: cosa mostra adesso B1?"]],
    [2, "Provoca un errore di divisione.", ["#DIV/0!", "0", "10", "#NOME?"], "Una cella vuota vale zero: dividere per zero dà #DIV/0!.", ["In un foglio vuoto scrivi 10 in A1.", "Lascia vuota la cella C1.", "In B1 scrivi =A1/C1 e premi Invio.", "Domanda: cosa compare in B1?"]]
