export const EIP_QUESTIONS = Object.entries(EIP_RAW).flatMap(([topic, rows]) => rows.map((r, i) => {
  const q = { id: `eip_${topic}_${String(i + 1).padStart(2, '0')}`, topic, type: 'mc', level: r[0] >= 3 || r[4] ? 'applicazione' : 'riconoscimento',
    difficulty: Math.min(3, r[0]), eipLevel: r[0], text: r[1], options: r[2], answer: 0, explanation: r[3], source: 'eipass_std', trap: null, origin: 'content-pack' };
  if (r[4]) q.pc = r[4];
  return q;
}));
export const EIP_MODULE_OF = Object.fromEntries(EIP_TOPICS.map(t => [t.id, t.module]));
